type UpsertWgHubParams struct {
	PrivateKeyEnc []byte
	PublicKey     string
	ListenPort    int64
	Address       string
	OverlayCidr   string
}

func (q *Queries) UpsertWgHub(ctx context.Context, arg UpsertWgHubParams) error {
	_, err := q.db.ExecContext(ctx, upsertWgHub,
		arg.PrivateKeyEnc,
		arg.PublicKey,
		arg.ListenPort,
		arg.Address,
		arg.OverlayCidr,
	)
	return err
}
